mod match_token;

use syn::visit_mut::VisitMut;

struct Expand;

impl VisitMut for Expand {
    fn visit_expr_mut(&mut self, expr: &mut syn::Expr) {
        if let syn::Expr::Macro(m) = expr {
            if m.mac.path.is_ident("match_token") {
                let expanded = match_token::expand(m.mac.tokens.clone());
                *expr = syn::parse2::<syn::Expr>(expanded).expect("expanded match_token! is an expression");
            }
        }
        syn::visit_mut::visit_expr_mut(self, expr);
    }
}

fn main() {
    let mut args = std::env::args().skip(1);
    let input = args.next().expect("usage: expand-rules RULES_IN OUT");
    let output = args.next().expect("usage: expand-rules RULES_IN OUT");
    let text = std::fs::read_to_string(&input).expect("read input");
    let mut file = syn::parse_file(&text).expect("parse input");
    file.items.retain(|item| !matches!(item, syn::Item::Use(u) if quote::quote!(#u).to_string().contains("match_token")));
    Expand.visit_file_mut(&mut file);
    let body = prettyplease::unparse(&file);
    let header = "// Generated by vendor/tools/expand-rules from rules.in.rs: match_token! expanded, so the build needs no proc macro.\n// Edit rules.in.rs and regenerate: cargo run --manifest-path vendor/tools/expand-rules/Cargo.toml -- rules.in.rs rules.rs\n\n";
    std::fs::write(&output, format!("{header}{body}")).expect("write output");
}
